def scoreOfStudents(s: str, answers: list[int]) -> int:
    # Split expression into numbers and operators
    nums, ops = [], []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            nums.append(int(s[i]))
        else:
            ops.append(s[i])
        i += 1

    n = len(nums)

    # Helper: get all possible results for [l, r], inclusive
    from functools import lru_cache

    BIG = 1001  # stands for "any value > 1000" (it can only drop back to 0 by multiplying with 0)

    @lru_cache(None)
    def dfs(l, r):
        results = set()
        if l == r:
            results.add(nums[l])
            return results
        for k in range(l, r):
            left = dfs(l, k)
            right = dfs(k+1, r)
            op = ops[k]
            for a in left:
                for b in right:
                    if op == '*' and (a == 0 or b == 0):
                        val = 0
                    elif a == BIG or b == BIG:
                        val = BIG
                    elif op == '+':
                        val = min(a + b, BIG)
                    else:  # '*'
                        val = min(a * b, BIG)
                    results.add(val)
        return results

    # Compute the correct answer using normal evaluation
    def eval_correct(nums, ops):
        n = len(nums)
        stack = [nums[0]]
        for idx, op in enumerate(ops):
            if op == '+':
                stack.append(nums[idx+1])
            else:  # '*'
                stack[-1] *= nums[idx+1]
        return sum(stack)

    correct = eval_correct(nums, ops)
    possible = dfs(0, n-1)
    total = 0
    for ans in answers:
        if ans == correct:
            total += 5
        elif ans in possible:
            total += 2
    return total
